// Query plans: a random query as plain data.
//
// The generator never touches the builder. It produces a `Plan` — which source,
// which conditions, what to select — that `build.ts` turns into builder calls
// and `model.ts` evaluates in JS. Keeping the plan as data is what makes a
// failure readable: the plan is shrunk, and the report prints it.
//
// Expressions are generated by *sort* (number, string, nullable string, time)
// so a plan is well-typed by construction, and the builder refusing one is a
// finding rather than noise.
import { Gen } from "../../effect-prop/src/index"
import type { FuzzDialect } from "./dialects/types"
import { nastyText, wellFormed } from "./values"

// The fixture (tests/core-cases.ts): five orders, four customers, two orgs.
export const ORDER_COLUMNS = {
	OrgId: "str",
	Id: "num",
	Customer: "str",
	Amount: "num",
	Status: "str",
	Note: "nstr",
	Created: "time",
} as const
export const CUSTOMER_COLUMNS = { OrgId: "str", Name: "str", Tier: "str" } as const
export type OrderColumn = keyof typeof ORDER_COLUMNS
export type CustomerColumn = keyof typeof CUSTOMER_COLUMNS
export type Sort = "num" | "str" | "nstr" | "time"

/** Values the fixture's string columns hold, so equality and LIKE sometimes match. */
const FIXTURE_STRINGS = ["org_1", "org_2", "acme", "globex", "initech", "umbrella", "paid", "open", "void", "rush", "it's", "gold", "silver", "bronze", "platinum"]
const T0 = Date.UTC(2026, 0, 1)
// Expressions

export type ArithOp = "add" | "sub" | "mul" | "div" | "mod"
export type Expr =
	| { readonly k: "col"; readonly col: OrderColumn }
	| { readonly k: "jcol"; readonly col: CustomerColumn }
	| { readonly k: "num"; readonly v: number }
	| { readonly k: "str"; readonly v: string }
	| { readonly k: "arith"; readonly op: ArithOp; readonly l: Expr; readonly r: Expr | number }
	| { readonly k: "coalesce"; readonly e: Expr; readonly fallback: Expr }

/** A comparison's right-hand side: a plain value, a param, or another expression. */
export type Operand =
	| { readonly k: "value"; readonly v: number | string }
	/** A time, in the three forms a DateTime comparison accepts. */
	| { readonly k: "time"; readonly ms: number; readonly form: "DateTime" | "Date" | "string" }
	| { readonly k: "param"; readonly kind: "int" | "string" | "dateTime"; readonly v: number | string }
	| { readonly k: "expr"; readonly e: Expr }

export type CmpOp = "eq" | "neq" | "gt" | "gte" | "lt" | "lte"
export type Cond =
	| { readonly k: "cmp"; readonly op: CmpOp; readonly l: Expr; readonly r: Operand }
	| { readonly k: "like"; readonly op: "like" | "notLike" | "ilike"; readonly l: Expr; readonly pattern: string }
	/** `l.contains(needle)` and its siblings: the needle is text, never a pattern, whatever characters it holds. */
	| { readonly k: "match"; readonly op: "contains" | "startsWith" | "endsWith"; readonly l: Expr; readonly needle: Operand; readonly insensitive: boolean }
	| { readonly k: "null"; readonly op: "isNull" | "isNotNull"; readonly e: Expr }
	| { readonly k: "between"; readonly neg: boolean; readonly e: Expr; readonly lo: Operand; readonly hi: Operand }
	| { readonly k: "in"; readonly neg: boolean; readonly e: Expr; readonly values: ReadonlyArray<number | string> }
	| { readonly k: "and" | "or"; readonly style: "method" | "fn"; readonly cs: ReadonlyArray<Cond> }
	| { readonly k: "not"; readonly c: Cond }
	| { readonly k: "const"; readonly v: boolean }
	/** `$.OrgId.eq(param.string("orgId"))`: the tenant predicate, wherever it lands. */
	| { readonly k: "tenant"; readonly side: "orders" | "customers" }

export type Agg =
	| { readonly k: "count" }
	| { readonly k: "countIf"; readonly c: Cond }
	| { readonly k: "sum" | "min" | "max"; readonly e: Expr }

export interface RowsShape {
	readonly k: "rows"
	readonly select: ReadonlyArray<readonly [string, Expr]>
	readonly distinct: boolean
	readonly orderBy: ReadonlyArray<readonly [string, "asc" | "desc"]>
	readonly limit?: number
	readonly offset?: number
}
export interface AggShape {
	readonly k: "agg"
	readonly keys: ReadonlyArray<readonly [string, Expr]>
	readonly aggs: ReadonlyArray<readonly [string, Agg]>
	readonly having: ReadonlyArray<{ readonly agg: Agg; readonly op: CmpOp; readonly v: number }>
	readonly orderBy: ReadonlyArray<readonly [string, "asc" | "desc"]>
	readonly limit?: number
	readonly offset?: number
}

export interface Plan {
	/** The value `param.string("orgId")` is given. */
	readonly orgId: string
	readonly join?: "inner" | "left"
	readonly where: ReadonlyArray<Cond>
	readonly shape: RowsShape | AggShape
	/** The same rows through a subquery: `fromQuery(query, "w").select()`, or `.select(...names)`. */
	readonly wrap: false | "all" | "names"
	readonly crossTenant: boolean
}

// Generators
//
// Native effect-prop generators: the simplest alternative comes first in every
// choice, so a failing plan shrinks toward a bare `SELECT Id`, and each
// expression and condition is a labelled span, so the shrinker can replace one
// with a sub-expression of the same sort.

export interface GenOptions {
	/** Strings for comparisons and LIKE patterns: anything, or only what sorts the same everywhere. */
	readonly strings: Gen.Gen<string>
	/** Whether the dialect has ILIKE (`FuzzDialect.ilike`). */
	readonly ilike: boolean
	/** Maximum recursive expression/condition depth; smoke plans default to two. */
	readonly depth?: number
}

/** Mostly the fixture's own numbers (Id 1–5, Amount 5/7/10/20/99), so comparisons split the rows. */
const smallInt = Gen.weighted([2, Gen.element(0, 1, 2, 3, 4, 5, 6, 7, 10, 20, 99)], [1, Gen.int(-20, 120)])
const divisor = Gen.oneOf(Gen.int(1, 9), Gen.int(-9, -1))
/** Around the fixture's `Created` range (00:00–00:40), at millisecond precision. */
const time = Gen.oneOf(
	Gen.map(Gen.int(0, 4), (i) => T0 + i * 600_000),
	Gen.int(T0 - 3_600_000, T0 + 6_000_000),
)
const text = (options: GenOptions): Gen.Gen<string> => Gen.oneOf(Gen.elements(FIXTURE_STRINGS), options.strings)

const expr = (sort: Sort, joined: boolean, depth: number, options: GenOptions): Gen.Gen<Expr> => {
	const cols = (Object.keys(ORDER_COLUMNS) as OrderColumn[]).filter((c) => ORDER_COLUMNS[c] === sort)
	const jcols = joined ? (Object.keys(CUSTOMER_COLUMNS) as CustomerColumn[]).filter((c) => CUSTOMER_COLUMNS[c] === sort) : []
	const leaves: Array<Gen.Gen<Expr>> = [
		...(cols.length > 0 ? [Gen.map(Gen.elements(cols), (col): Expr => ({ k: "col", col }))] : []),
		...(jcols.length > 0 ? [Gen.map(Gen.elements(jcols), (col): Expr => ({ k: "jcol", col }))] : []),
	]
	if (sort === "num") {
		leaves.push(Gen.map(smallInt, (v): Expr => ({ k: "num", v })))
		if (depth > 0) {
			const sub = expr("num", joined, depth - 1, options)
			leaves.push(Gen.struct({ k: Gen.constant("arith"), op: Gen.element<ReadonlyArray<ArithOp>>("add", "sub", "mul", "div", "mod"), l: sub, r: Gen.oneOf(divisor, sub) }))
		}
	}
	if (sort === "str") {
		leaves.push(Gen.map(text(options), (v): Expr => ({ k: "str", v })))
		if (depth > 0) {
			leaves.push(Gen.struct({ k: Gen.constant("coalesce"), e: expr("nstr", joined, depth - 1, options), fallback: expr("str", joined, 0, options) }))
		}
	}
	return Gen.labeled(Gen.oneOf(...leaves), `expr:${sort}`)
}

const valueOf = (sort: Sort, options: GenOptions): Gen.Gen<Operand> => {
	switch (sort) {
		case "num":
			return Gen.weighted(
				[3, Gen.map(smallInt, (v): Operand => ({ k: "value", v }))],
				[3, Gen.map(smallInt, (v): Operand => ({ k: "param", kind: "int", v }))],
				// A fraction against an integer column: `Amount > 9.5`.
				[1, Gen.map(Gen.int(-40, 240), (n): Operand => ({ k: "value", v: n / 2 + 0.25 }))],
			)
		case "str":
		case "nstr":
			return Gen.oneOf(
				Gen.map(text(options), (v): Operand => ({ k: "value", v })),
				Gen.map(text(options), (v): Operand => ({ k: "param", kind: "string", v })),
			)
		case "time":
			return Gen.oneOf(
				Gen.struct({ k: Gen.constant("time"), ms: time, form: Gen.element("DateTime", "Date", "string") }),
				Gen.map(time, (ms): Operand => ({ k: "param", kind: "dateTime", v: ms })),
			)
	}
}

/** A comparable right-hand side for `sort`: mostly values, sometimes another expression of the sort. */
const operand = (sort: Sort, joined: boolean, options: GenOptions): Gen.Gen<Operand> =>
	sort === "time"
		? valueOf(sort, options)
		: Gen.weighted([3, valueOf(sort, options)], [1, Gen.map(expr(sort === "nstr" ? "str" : sort, joined, 1, options), (e): Operand => ({ k: "expr", e }))])

/** LIKE patterns over the fixture's letters; `\` only ever escapes `%`, `_` or `\`, which every database must agree on. */
const soupPattern = Gen.map(
	Gen.array(Gen.element("%", "_", "\\%", "\\_", "\\\\", "a", "c", "e", "m", "i", "o", "p", "AC", "G", "'", "s"), { maxLength: 5 }),
	(parts) => parts.join(""),
)

/**
 * A fixture value, edited letter by letter: re-cased, or replaced by `_` or `%`;
 * a literal `_` or `%` in the value is escaped. Unlike letter soup, these
 * patterns select rows, so case and escape rules change the result where
 * dialects differ. A pattern that matches nothing tests nothing.
 */
const fixturePattern = Gen.map(
	Gen.tuple(Gen.elements(FIXTURE_STRINGS), Gen.array(Gen.element("keep", "keep", "keep", "upper", "under", "pct"), { minLength: 1, maxLength: 9 })),
	([value, edits]) =>
		[...value]
			.map((ch, i) => {
				const edit = edits[i % edits.length]
				if (edit === "under") return "_"
				if (edit === "pct") return "%"
				const kept = edit === "upper" ? ch.toUpperCase() : ch
				return kept === "_" || kept === "%" || kept === "\\" ? `\\${kept}` : kept
			})
			.join(""),
)

const likePattern = Gen.oneOf(soupPattern, fixturePattern)

/** Every character some dialect's LIKE or GLOB reads as a wildcard, a class or an escape. */
const WILDCARDS = ["%", "_", "*", "?", "[", "]", "\\", "^"] as const

/**
 * What to look for in `l`. Mostly a piece of a string that is there, so the
 * match selects rows: of the literal when `l` is one, of a fixture value
 * otherwise. Sometimes that piece with one character swapped for a wildcard,
 * which must then match as itself and so, usually, not at all.
 */
const needleText = (l: Expr, options: GenOptions): Gen.Gen<string> => {
	const piece = Gen.gen(function* () {
		const chars = [...(l.k === "str" ? l.v : yield* Gen.elements(FIXTURE_STRINGS))]
		const from = yield* Gen.int(0, chars.length)
		return chars.slice(from, yield* Gen.int(from, chars.length))
	})
	return Gen.weighted(
		[4, Gen.map(piece, (chars) => chars.join(""))],
		[2, text(options)],
		[
			2,
			Gen.gen(function* () {
				const chars = yield* piece
				const wildcard = yield* Gen.elements(WILDCARDS)
				if (chars.length === 0) return wildcard
				chars[yield* Gen.int(0, chars.length - 1)] = wildcard
				return chars.join("")
			}),
		],
		[1, Gen.map(piece, (chars) => chars.join("").toUpperCase())],
	)
}

const textMatch = (joined: boolean, options: GenOptions): Gen.Gen<Cond> =>
	Gen.gen(function* () {
		const l = yield* expr(yield* Gen.element<ReadonlyArray<Sort>>("str", "nstr"), joined, 1, options)
		const looked = yield* needleText(l, options)
		const needle = yield* Gen.weighted<ReadonlyArray<readonly [number, Gen.Gen<Operand>]>>(
			[3, Gen.constant({ k: "value", v: looked })],
			[2, Gen.constant({ k: "param", kind: "string", v: looked })],
			[1, Gen.map(expr("str", joined, 0, options), (e): Operand => ({ k: "expr", e }))],
		)
		return { k: "match", op: yield* Gen.element("contains", "startsWith", "endsWith"), l, needle, insensitive: yield* Gen.weightedBoolean(0.3) }
	})

const cond = (joined: boolean, depth: number, options: GenOptions): Gen.Gen<Cond> => {
	const leaf: Gen.Gen<Cond> = Gen.oneOf(
		Gen.flatMap(Gen.element<ReadonlyArray<Sort>>("num", "str", "nstr", "time"), (sort) =>
			Gen.struct({ k: Gen.constant("cmp"), op: Gen.element<ReadonlyArray<CmpOp>>("eq", "neq", "gt", "gte", "lt", "lte"), l: expr(sort, joined, 1, options), r: operand(sort, joined, options) }),
		),
		Gen.flatMap(Gen.element<ReadonlyArray<Sort>>("str", "nstr"), (sort) =>
			Gen.struct({ k: Gen.constant("like"), op: Gen.elements(options.ilike ? (["like", "notLike", "ilike"] as const) : (["like", "notLike"] as const)), l: expr(sort, joined, 0, options), pattern: likePattern }),
		),
		textMatch(joined, options),
		Gen.struct({ k: Gen.constant("null"), op: Gen.element("isNull", "isNotNull"), e: Gen.oneOf(expr("nstr", joined, 0, options), expr("str", joined, 0, options)) }),
		Gen.flatMap(Gen.element<ReadonlyArray<Sort>>("num", "str", "time"), (sort) =>
			Gen.struct({ k: Gen.constant("between"), neg: Gen.boolean, e: expr(sort, joined, 1, options), lo: valueOf(sort, options), hi: valueOf(sort, options) }),
		),
		Gen.flatMap(Gen.element<ReadonlyArray<Sort>>("num", "str", "nstr"), (sort) =>
			Gen.struct({
				k: Gen.constant("in"),
				neg: Gen.boolean,
				e: expr(sort, joined, 0, options),
				values: Gen.array<number | string>(sort === "num" ? smallInt : text(options), { maxLength: 4 }),
			}),
		),
		Gen.map(Gen.boolean, (v): Cond => ({ k: "const", v })),
		Gen.elements<Cond>([{ k: "tenant", side: "orders" }, ...(joined ? [{ k: "tenant", side: "customers" } as const] : [])]),
	)
	if (depth === 0) return Gen.labeled(leaf, "cond")
	const sub = cond(joined, depth - 1, options)
	return Gen.labeled(
		Gen.weighted(
			[4, leaf],
			[2, Gen.struct({ k: Gen.element("and", "or"), style: Gen.element("method", "fn"), cs: Gen.array(sub, { minLength: 2, maxLength: 3 }) })],
			[1, Gen.map(sub, (c): Cond => ({ k: "not", c }))],
		),
		"cond",
	)
}

const agg = (joined: boolean, options: GenOptions): Gen.Gen<Agg> =>
	Gen.oneOf(
		Gen.constant<Agg>({ k: "count" }),
		Gen.map(cond(joined, 1, options), (c): Agg => ({ k: "countIf", c })),
		Gen.struct({ k: Gen.element("sum", "min", "max"), e: expr("num", joined, 1, options) }),
	)

const aliasesOf = (n: number, prefix: string) => Array.from({ length: n }, (_, i) => `${prefix}${i}`)
const direction = Gen.element("asc", "desc")
type Ordering = Pick<RowsShape, "orderBy" | "limit" | "offset">

/** An ORDER BY over `aliases`, completed with `unique` so LIMIT/OFFSET pick a determined set. */
const ordering = (aliases: ReadonlyArray<string>, unique: ReadonlyArray<string>): Gen.Gen<Ordering> =>
	Gen.gen(function* () {
		const keys: Array<readonly [string, "asc" | "desc"]> = []
		for (const key of yield* Gen.subsequence(aliases)) keys.push([key, yield* direction])
		const limit = yield* Gen.weighted([1, Gen.constant(undefined)], [4, Gen.weighted([4, Gen.int(1, 6)], [1, Gen.constant(0)])])
		const offset = yield* Gen.weighted([1, Gen.constant(undefined)], [2, Gen.int(0, 3)])
		const total = yield* Gen.boolean
		const complete = limit !== undefined || offset !== undefined || total
		const tail = complete ? unique.filter((u) => !keys.some(([k]) => k === u)).map((u) => [u, "asc"] as const) : []
		return { orderBy: [...keys, ...tail], limit, offset }
	})

const rowsShape = (joined: boolean, options: GenOptions): Gen.Gen<RowsShape> =>
	Gen.gen(function* () {
		const exprs = yield* Gen.array(Gen.flatMap(Gen.element<ReadonlyArray<Sort>>("num", "str", "nstr", "time"), (sort) => expr(sort, joined, options.depth ?? 2, options)), { maxLength: 4 })
		// `id` identifies orders; joined rows also order by every selected alias to break duplicate-key ties.
		const select: Array<readonly [string, Expr]> = [["id", { k: "col", col: "Id" }], ...exprs.map((e, i) => [`e${i}`, e] as const)]
		const distinct = yield* Gen.boolean
		const order = yield* ordering(select.map(([a]) => a), joined ? select.map(([a]) => a) : ["id"])
		return { k: "rows", select, distinct, ...order }
	})

const keyExpr = (joined: boolean): Gen.Gen<Expr> =>
	Gen.elements<Expr>([
		{ k: "col", col: "Customer" },
		{ k: "col", col: "Status" },
		{ k: "col", col: "OrgId" },
		{ k: "col", col: "Note" },
		...(joined ? [{ k: "jcol", col: "Tier" } as const, { k: "jcol", col: "Name" } as const] : []),
	])

const aggShape = (joined: boolean, options: GenOptions): Gen.Gen<AggShape> =>
	Gen.gen(function* () {
		const keys = yield* Gen.uniqueArray(keyExpr(joined), { maxLength: 2, key: (e) => JSON.stringify(e) })
		const aggs = yield* Gen.array(agg(joined, options), { minLength: 1, maxLength: 3 })
		const keyAliases = aliasesOf(keys.length, "k")
		const aggAliases = aliasesOf(aggs.length, "a")
		const having =
			keys.length === 0 ? [] : yield* Gen.array(Gen.struct({ agg: agg(joined, options), op: Gen.element<ReadonlyArray<CmpOp>>("eq", "neq", "gt", "gte", "lt", "lte"), v: smallInt }), { maxLength: 2 })
		// A global aggregate is one row; only grouped results page.
		const order: Ordering = keys.length === 0 ? { orderBy: [], limit: undefined, offset: undefined } : yield* ordering([...keyAliases, ...aggAliases], keyAliases)
		return {
			k: "agg",
			keys: keys.map((e, i) => [keyAliases[i]!, e] as const),
			aggs: aggs.map((a, i) => [aggAliases[i]!, a] as const),
			having,
			...order,
		}
	})

const orgId = Gen.weighted([6, Gen.constant("org_1")], [2, Gen.constant("org_2")], [1, Gen.constant("org_3")])
const join = Gen.weighted([1, Gen.constant(undefined)], [2, Gen.element("inner", "left")])

// Short: every entry is ANDed, and a long conjunction of random predicates is almost always empty.
const where = (joined: boolean, options: GenOptions): Gen.Gen<ReadonlyArray<Cond>> =>
	Gen.oneOf(
		Gen.constant([]),
		Gen.array(Gen.weighted([1, Gen.constant<Cond>({ k: "tenant", side: "orders" })], [3, cond(joined, options.depth ?? 2, options)]), { minLength: 1, maxLength: 2 }),
	)

/**
 * `unionAll(branch, …)` with the union's own ORDER BY, LIMIT and OFFSET. Each
 * branch is a row plan selecting the same aliases, each alias of one sort in
 * every branch, so the union is well-typed by construction; a branch may have
 * its own join, filter, DISTINCT, ORDER BY and LIMIT.
 */
export interface UnionPlan {
	readonly orgId: string
	readonly branches: ReadonlyArray<Plan>
	readonly orderBy: ReadonlyArray<readonly [string, "asc" | "desc"]>
	readonly limit?: number
	readonly offset?: number
	readonly crossTenant: boolean
}

const branch = (org: string, sorts: ReadonlyArray<Sort>, options: GenOptions): Gen.Gen<Plan> =>
	Gen.gen(function* () {
		const joinKind = yield* join
		const joined = joinKind !== undefined
		const select: Array<readonly [string, Expr]> = [["id", { k: "col", col: "Id" }]]
		for (const [i, sort] of sorts.entries()) select.push([`e${i}`, yield* expr(sort, joined, options.depth ?? 2, options)])
		const filter = yield* where(joined, options)
		const distinct = yield* Gen.boolean
		const order = yield* ordering(select.map(([a]) => a), joined ? select.map(([a]) => a) : ["id"])
		return { orgId: org, join: joinKind, where: filter, shape: { k: "rows", select, distinct, ...order }, wrap: false, crossTenant: false }
	})

/**
 * The union's ordering. Rows of different branches can tie on every alias but
 * one, so it pages only when ordered by every alias: then tied rows are equal
 * rows, and which of them LIMIT keeps does not matter.
 */
const unionOrdering = (aliases: ReadonlyArray<string>): Gen.Gen<Ordering> =>
	Gen.oneOf(
		Gen.constant<Ordering>({ orderBy: [], limit: undefined, offset: undefined }),
		Gen.gen(function* () {
			const orderBy: Array<readonly [string, "asc" | "desc"]> = []
			for (const key of yield* Gen.shuffled(aliases)) orderBy.push([key, yield* direction])
			return { orderBy, limit: yield* Gen.option(Gen.int(0, 8)), offset: yield* Gen.option(Gen.int(0, 4)) }
		}),
		Gen.gen(function* () {
			const keys = (yield* Gen.shuffled(aliases)).slice(0, yield* Gen.int(1, aliases.length))
			return { orderBy: keys.map((k) => [k, "asc"] as const), limit: undefined, offset: undefined }
		}),
	)

export const unionPlan = (options: GenOptions): Gen.Gen<UnionPlan> =>
	Gen.gen(function* () {
		const org = yield* orgId
		const sorts = yield* Gen.array(Gen.element<ReadonlyArray<Sort>>("num", "str", "nstr", "time"), { maxLength: 3 })
		const branches = yield* Gen.array(branch(org, sorts, options), { minLength: 2, maxLength: 3 })
		const crossTenant = yield* Gen.boolean
		const order = yield* unionOrdering(["id", ...sorts.map((_, i) => `e${i}`)])
		return { orgId: org, branches, crossTenant, ...order }
	})

export const plan = (options: GenOptions): Gen.Gen<Plan> =>
	Gen.gen(function* () {
		const joinKind = yield* join
		const joined = joinKind !== undefined
		return {
			orgId: yield* orgId,
			join: joinKind,
			where: yield* where(joined, options),
			shape: yield* Gen.weighted([3, rowsShape(joined, options)], [2, aggShape(joined, options)]),
			wrap: yield* Gen.element(false, "all", "names"),
			crossTenant: yield* Gen.boolean,
		}
	})

/** Every string the oracle compares by byte order: plain, so collation never enters. */
export const plainOptions = (dialect: FuzzDialect): GenOptions => ({
	strings: Gen.string({ char: Gen.charOf("abcdeghiklmnoprstuwxy_' -"), maxLength: 8 }),
	ilike: dialect.ilike,
})
/** Strings from the nasty generator: for escaping, where the model only needs equality. */
export const nastyOptions = (dialect: FuzzDialect): GenOptions => ({
	strings: nastyText(dialect.strings).pipe(Gen.filter((s) => wellFormed(s))),
	ilike: dialect.ilike,
})
